cat > sf-voter-guides/scraper/scrape.py <<'PY'
import argparse
import hashlib
import json
import re
import time
import unicodedata
import urllib.error
import urllib.parse
import urllib.request
import urllib.robotparser
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path
from bs4 import BeautifulSoup

ROOT = Path(__file__).resolve().parents[1]
CACHE = ROOT / 'cache'
DATA = ROOT / 'data'
CONFIG = json.loads((ROOT / 'scraper/config.json').read_text())
UA = 'SFGuideComparison/1.0 (+https://github.com/elizabethsiegle/demos3idkman)'
AGGREGATOR = 'https://sfendorsements.com/'


def slug(text):
    return re.sub(r'[^a-z0-9]+', '-', unicodedata.normalize('NFKD', text).encode('ascii', 'ignore').decode().lower()).strip('-')


def clean(text):
    return ' '.join(text.split())


class Fetcher:
    def __init__(self, refresh=False):
        self.refresh = refresh
        self.policies = {}
        self.notes = []
        self.last_request = 0
        CACHE.mkdir(exist_ok=True)

    def raw(self, url):
        path = CACHE / (hashlib.sha256(url.encode()).hexdigest() + '.html')
        meta = path.with_suffix('.json')
        if path.exists() and not self.refresh:
            timestamp = json.loads(meta.read_text())['retrieved_at'] if meta.exists() else datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat()
            return path.read_text(), timestamp
        time.sleep(max(0, 1 - (time.monotonic() - self.last_request)))
        self.last_request = time.monotonic()
        with urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': UA}), timeout=30) as response:
            text = response.read().decode('utf-8', errors='replace')
        timestamp = datetime.now(timezone.utc).isoformat()
        path.write_text(text)
        meta.write_text(json.dumps({'url': url, 'retrieved_at': timestamp}))
        return text, timestamp

    def get(self, url):
        origin = urllib.parse.urlsplit(url)
        host = origin.scheme + '://' + origin.netloc
        if host not in self.policies:
            try:
                robots, _ = self.raw(host + '/robots.txt')
                if '<html' in robots[:1000].lower():
                    self.notes.append(host + ': robots.txt returns HTML; no applicable robots directives.')
                    robots = ''
                policy = urllib.robotparser.RobotFileParser()
                policy.parse(robots.splitlines())
                self.policies[host] = policy
            except urllib.error.HTTPError as error:
                if error.code not in (404, 410):
                    raise RuntimeError(f'robots.txt unavailable ({error.code}); skipped') from error
                self.policies[host] = None
        policy = self.policies[host]
        if policy and not policy.can_fetch(UA, url):
            raise RuntimeError('robots.txt disallows this URL')
        if policy:
            delay = policy.crawl_delay(UA) or policy.crawl_delay('*') or 1
            time.sleep(max(0, delay - (time.monotonic() - self.last_request)))
        return self.raw(url)


def topics_for(text, kind):
    words = {
        'housing': r'hous|home|tenant|transfer tax', 'transit': r'transit|muni|bart|highway|transport',
        'taxes and budget': r'tax|fund|bond|budget|bank|finance|controller|treasurer',
        'governance and charter': r'charter|commission|administrator|executive|governor|supervisor|equalization|assessor',
        'public safety': r'police|safety|defender|attorney|court|justice',
        'education': r'school|education|college|instruction',
        'elections and voting': r'ballot|vot|recall|campaign|secretary', 'health': r'health|clinic|immun|insurance'
    }
    return [topic for topic, pattern in words.items() if re.search(pattern, text, re.I)] or ['governance and charter']


def stance_for(value, kind):
    value = clean(value)
    if not value:
        return 'no_recommendation_found'
    if re.search(r'no (position|recommendation|endorsement)|neutral|abstain|no consensus', value, re.I):
        return 'no_position'
    if kind == 'measure':
        if re.fullmatch(r'(hell )?yes[! ]*', value, re.I):
            return 'yes'
        if re.fullmatch(r'(hell )?no[! ]*', value, re.I):
            return 'no'
        return 'no_recommendation_found'
    return None


def run(refresh=False):
    fetcher = Fetcher(refresh)
    html, agg_time = fetcher.get(AGGREGATOR)
    soup = BeautifulSoup(html, 'html.parser')
    guides = [dict(zip(['id', 'name', 'camp', 'aggregator_name', 'url', 'type'], row)) for row in CONFIG['guides']]
    by_name = {guide['aggregator_name']: guide for guide in guides}
    contests = {}
    positions = {}
    source_issues = []
    direct_count = Counter()

    def put(guide, contest, stance, url, timestamp, confidence='high', **extra):
        positions[(guide['id'], contest['id'])] = dict(guide_id=guide['id'], contest_id=contest['id'], stance=stance, rationale=None, source_url=url, retrieved_at=timestamp, confidence=confidence, **extra)

    for table in soup.select('table'):
        heading = table.select_one('h2')
        if not heading:
            continue
        section = heading.get_text(' ', strip=True)
        columns = table.select('thead tr')[-1].select('th')[1:]
        section_contests = []
        for th in columns:
            title = clean(th.get_text(' ', strip=True))
            if title == 'House CA-15':
                section_contests.append(None)
                continue
            local = 'Local ballot' in section
            retention = 'Judicial retention' in section
            measure = 'ballot measures' in section or retention
            regional = title == 'Regional Transit Measure' or title.startswith('BART')
            level = 'regional' if regional else 'city' if local or section in ['Citywide local races', 'Board of education, community college, and BART'] else 'district' if 'supervisor' in section.lower() or 'Assembly' in title else 'federal' if title.startswith('House') else 'state'
            name = ('SF ' if local else 'CA ' if 'State ballot' in section else '') + title
            cid = 'regional-rtm' if title == 'Regional Transit Measure' else slug(name)
            contest = dict(id=cid, name=name, level=level, kind='measure' if measure else 'race', description=title, full_title=title, topics=[], candidates=[], candidate_list_complete=False, ballot_order=len(contests), description_source_url=AGGREGATOR)
            if retention:
                contest['subtype'] = 'judicial retention'
            contests[cid] = contest
            section_contests.append(contest)
        for tr in table.select('tbody tr'):
            cells = tr.select('td')
            if not cells:
                continue
            button = cells[0].select_one('button')
            guide = by_name.get(button.get_text(strip=True) if button else '')
            if not guide:
                continue
            for contest, cell in zip(section_contests, cells[1:]):
                if not contest:
                    continue
                value = clean(cell.get_text(' ', strip=True))
                stance = stance_for(value, contest['kind'])
                extra = {'collection': 'aggregator'}
                if stance is None:
                    names = [clean(x.get_text(' ', strip=True)) for x in cell.select('strong')]
                    if not names:
                        stance = 'no_recommendation_found'
                        extra['review_note'] = 'Candidate cell has no unambiguous name elements: ' + value[:100]
                    else:
                        ids = []
                        for name in names:
                            candidate = dict(id=slug(name), name=name)
                            ids.append(candidate['id'])
                            if candidate not in contest['candidates']:
                                contest['candidates'].append(candidate)
                        stance = 'candidate:' + ids[0] if len(ids) == 1 else 'ranked:' + json.dumps(ids, separators=(',', ':'))
                        extra['selection_type'] = 'single' if len(ids) == 1 else 'unordered slate' if 'three seats' in contest['name'] else 'order unverified'
                confidence = 'low' if stance != 'no_recommendation_found' else 'high'
                put(guide, contest, stance, AGGREGATOR, agg_time, confidence, **extra)

    def measure(code, level):
        return contests.get('regional-rtm' if code == 'RTM' else slug(('SF' if level == 'city' else 'CA') + ' Prop ' + code))

    def direct(guide, contest, value, url, timestamp, description=None):
        if not contest:
            return
        stance = stance_for(value, contest['kind'])
        if stance is None or stance == 'no_recommendation_found':
            return
        previous = positions.get((guide['id'], contest['id']))
        extra = {'collection': 'direct'}
        if previous and previous['stance'] != stance:
            extra['review_note'] = 'Direct source differs from aggregator (' + previous['stance'] + '); direct source takes precedence.'
            source_issues.append(guide['name'] + ' / ' + contest['name'] + ': ' + extra['review_note'])
        put(guide, contest, stance, url, timestamp, **extra)
        direct_count[guide['id']] += 1
        if description and (contest['description'] == contest['full_title'] or guide['id'] == 'growsf'):
            contest.update(description=clean(description), full_title=clean(description), description_source_url=url)

    for guide in guides:
        try:
            html, timestamp = fetcher.get(guide['url'])
            page = BeautifulSoup(html, 'html.parser')
            if guide['id'] == 'sf-dems':
                link = next((a for a in page.select('a[href]') if '/endorsements/' in a['href'] and ('nov-3-2026' in a['href'] or 'november-2026' in a['href'])), None)
                if link:
                    guide['url'] = urllib.parse.urljoin(guide['url'], link['href'])
                    html, timestamp = fetcher.get(guide['url'])
                    page = BeautifulSoup(html, 'html.parser')
            guide['inspection'] = {'status': 'read', 'title': page.title.get_text(strip=True) if page.title else '', 'retrieved_at': timestamp}
            if not re.search(r'2026', page.get_text()):
                source_issues.append(guide['name'] + ': direct page does not identify the 2026 election; aggregator retained.')
                continue
            if guide['id'] == 'growsf':
                for block in page.select('[id^="prop-"]'):
                    heading = block.select_one('h3')
                    match = re.fullmatch(r'(Yes|No) on Proposition (\w+)', clean(heading.get_text(' ', strip=True))) if heading else None
                    if not match:
                        continue
                    value, code = match.groups()
                    desc = heading.find_next_sibling('p')
                    direct(guide, measure(code, 'city' if code.isalpha() and code != 'RTM' else 'state'), value, guide['url'] + '#' + block['id'], timestamp, desc.get_text(' ', strip=True) if desc else None)
            elif guide['id'] == 'spur':
                for block in page.select('article.node--type-ballot-measure'):
                    a = block.select_one('a[href]')
                    url = urllib.parse.urljoin(guide['url'], a['href'])
                    match = re.search(r'/(sf|ca|ba)-prop-([a-z0-9]+)-', url)
                    if not match:
                        continue
                    level, code = match.groups()
                    recommendation = block.select_one('.field--name-field-recommendation')
                    desc = block.select_one('.field--name-field-short-title')
                    value = re.sub(r'^Vote ', '', recommendation.get_text(strip=True))
                    direct(guide, measure(code.upper(), 'city' if level == 'sf' else 'state'), value, url, timestamp, desc.get_text(strip=True))
            elif guide['id'] == 'lwv':
                for block in page.select('[data-aid^="FAQ_QUESTION_RENDERED"]'):
                    match = re.search(r'Proposition (\w+): (.*?)\s*[—–]\s*(YES|NO|NEUTRAL)', block.get_text(' ', strip=True))
                    if match:
                        code, desc, value = match.groups()
                        direct(guide, measure(code, 'city'), value, guide['url'], timestamp, desc)
            elif guide['id'] == 'tenants':
                for block in page.select('.sftu-prop'):
                    code_el, value_el = block.select_one('.sftu-prop-number'), block.select_one('.sftu-status')
                    if not code_el or not value_el:
                        continue
                    match = re.search(r'Prop (RTM|[A-J]|\d+)', code_el.get_text())
                    if match:
                        code = match[1]
                        direct(guide, measure(code, 'city' if code.isalpha() else 'state'), value_el.get_text(' ', strip=True), guide['url'], timestamp)
            elif guide['id'] == 'milk':
                text = page.get_text(' ', strip=True)
                for pattern, level in [(r'(YES|NO POSITION|NO) on ([A-J]|RTM)\b', 'city'), (r'(YES|NO POSITION|NO) on Prop (\d+)\b', 'state')]:
                    for match in re.finditer(pattern, text):
                        direct(guide, measure(match[2], level), match[1], guide['url'], timestamp)
            elif guide['id'] == 'guardian':
                for block in page.select('p'):
                    text = clean(block.get_text(' ', strip=True))
                    match = re.fullmatch(r'Proposition\s+([A-J]|\d+)\s+(.*?)\s+(YES(?: YES)*|NO(?: NO)*)[!.]*', text, re.I)
                    if match:
                        code, desc, value = match.groups()
                        direct(guide, measure(code, 'city' if code.isalpha() else 'state'), value.split()[0], guide['url'], timestamp)
            elif guide['id'] == 'dsa':
                for heading in page.select('h1,h2,h3,h4'):
                    text = clean(heading.get_text(' ', strip=True))
                    match = re.search(r'Prop(?:osition)?\.?\s*([A-J]|RTM|\d+)\s*[:—–-]?\s*(.*)', text, re.I)
                    if not match:
                        continue
                    code = match[1].upper()
                    vicinity = text
                    for sibling in heading.next_siblings:
                        if getattr(sibling, 'name', '') in ['h1', 'h2', 'h3', 'h4']:
                            break
                        if getattr(sibling, 'get_text', None):
                            vicinity += ' ' + sibling.get_text(' ', strip=True)
                        if len(vicinity) > 800:
                            break
                    votes = set(re.findall(r'\b(?:Vote|Recommendation:|Recommend)\s+(YES|NO)\b', vicinity, re.I))
                    heading_vote = re.search(r'\b(YES|NO)\b', text)
                    value = heading_vote[1] if heading_vote else next(iter(votes)) if len(votes) == 1 else ''
                    direct(guide, measure(code, 'city' if code.isalpha() and code != 'RTM' else 'state'), value, guide['url'], timestamp)
                for a in page.select('a[href]'):
                    match = re.fullmatch(r'(Yes|No) Proposition ([BIDEF])', clean(a.get_text(' ', strip=True)))
                    if match:
                        direct(guide, measure(match[2], 'city'), match[1], urllib.parse.urljoin(guide['url'], a['href']), timestamp)
        except Exception as error:
            guide['inspection'] = {'status': 'unavailable', 'reason': str(error)}
            source_issues.append(guide['name'] + ': ' + str(error))
        finally:
            print(guide['name'] + ': ' + str(direct_count[guide['id']]) + ' direct positions', flush=True)

    for contest in contests.values():
        contest['topics'] = topics_for(contest['name'] + ' ' + contest['description'], contest['kind'])
        for guide in guides:
            if (guide['id'], contest['id']) not in positions:
                put(guide, contest, 'no_recommendation_found', guide['url'], guide.get('inspection', {}).get('retrieved_at', agg_time), collection='not found')
    for override in json.loads((DATA / 'manual_overrides.json').read_text()):
        key = (override['guide_id'], override['contest_id'])
        if key not in positions:
            raise ValueError('Unknown override guide/contest: ' + str(key))
        required = {'stance', 'source_url', 'retrieved_at', 'confidence', 'reason'}
        if not required.issubset(override):
            raise ValueError('Override requires stance, source_url, retrieved_at, confidence, reason')
        positions[key].update(override, collection='manual override')
    for guide in guides:
        guide['collection'] = f"HTML tables from SF Endorsements; {direct_count[guide['id']]} measure positions parsed directly. Candidate sets are aggregator-only unless manually reviewed."
    result = dict(election=CONFIG['election'], retrieved_at=agg_time, guides=guides, contests=list(contests.values()), positions=list(positions.values()), topics=CONFIG['topics'], report_error_url=CONFIG['report_error_url'], source_issues=source_issues + fetcher.notes)
    previous = json.loads((DATA / 'dataset.json').read_text()) if (DATA / 'dataset.json').exists() else None
    counts = Counter(p['guide_id'] for p in result['positions'] if p['stance'] not in ['no_recommendation_found', 'no_position'])
    old_counts = Counter(p['guide_id'] for p in previous['positions'] if p['stance'] not in ['no_recommendation_found', 'no_position']) if previous else Counter()
    old = {(p['guide_id'], p['contest_id']): p for p in previous['positions']} if previous else {}
    changes = [dict(guide_id=p['guide_id'], contest_id=p['contest_id'], before=old[(p['guide_id'], p['contest_id'])]['stance'], after=p['stance']) for p in result['positions'] if (p['guide_id'], p['contest_id']) in old and old[(p['guide_id'], p['contest_id'])]['stance'] != p['stance']]
    low = [p for p in result['positions'] if p['confidence'] == 'low']
    missing = [p for p in result['positions'] if p['stance'] == 'no_recommendation_found']
    report = ['# Data review', '', f"{len(guides)} guides · {len(contests)} contests · {sum(counts.values())} positions · {len(low)} low-confidence cells · {len(missing)} missing cells", '', 'Snapshot: ' + agg_time, '', '## Coverage', '', '| Guide | Positions | Direct measures | Change |', '|---|---:|---:|---:|']
    for guide in guides:
