        delta = counts[gid] - old_counts[gid]
        report.append(f"| {guide['name']} | {counts[gid]} | {direct_count[gid]} | {delta:+} {'DROP: REVIEW' if delta < 0 else ''} |")
    report += ['', '## Source limitations', ''] + ['- ' + note for note in result['source_issues']]
    report += ['', 'Candidate lists are discovered endorsements, not verified complete ballot rosters. Multi-name aggregator cells do not establish ranking order. No rationales are inferred from surrounding advocacy text.', '', '## Changed cells', ''] + [f"- {c['guide_id']} / {c['contest_id']}: {c['before']} → {c['after']}" for c in changes]
    report += ['', '## Low-confidence cells', '', '| Guide | Contest | Stance | Reason | Source |', '|---|---|---|---|---|']
    for p in low:
        report.append(f"| {p['guide_id']} | {p['contest_id']} | {p['stance']} | {p.get('review_note', 'Aggregator-only; direct confirmation required')} | [source]({p['source_url']}) |")
    report += ['', '## Missing cells', ''] + [f"- {p['guide_id']} / {p['contest_id']}: [checked source]({p['source_url']})" for p in missing]
    DATA.mkdir(exist_ok=True)
    (DATA / 'dataset.json').write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n')
    (DATA / 'changes.json').write_text(json.dumps(changes, indent=2) + '\n')
    (DATA / 'REVIEW.md').write_text('\n'.join(report) + '\n')
    print(f'{len(guides)} guides, {len(contests)} contests, {sum(direct_count.values())} direct positions, {len(low)} low-confidence cells')


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--refresh', action='store_true', help='Replace cached responses with fresh HTTP requests')
    run(parser.parse_args().refresh)
