export const hasPosition = p => !!p && !['no_position', 'no_recommendation_found'].includes(p.stance);
export function candidateIds(stance) {
  if (stance.startsWith('candidate:')) return [stance.slice(10)];
  if (stance.startsWith('ranked:')) return JSON.parse(stance.slice(7));
  return [];
}
export function positionKey(p) {
  const ids = candidateIds(p.stance);
  if (!ids.length) return p.stance;
  return JSON.stringify(p.selection_type === 'ranked' ? ids : ids.toSorted());
}
export function splitScore(positions, kind) {
  const active = positions.filter(hasPosition);
  if (!active.length) return { score: null, count: 0, majority: 0, leaders: [] };
  const counts = new Map();
  for (const p of active) {
    const choices = kind === 'race' ? candidateIds(p.stance) : [p.stance];
    for (const id of new Set(choices)) counts.set(id, (counts.get(id) ?? 0) + 1);
  }
  const majority = Math.max(...counts.values());
  const leaders = [...counts].filter(([, count]) => count === majority).map(([id]) => id);
  const supporters = kind === 'race' ? active.filter(p => candidateIds(p.stance).some(id => leaders.includes(id))).length : majority;
  return { score: (active.length - supporters) / active.length, count: active.length, majority: supporters, leaders };
}
export function bucket(score) {
  if (score === null) return 'No positions';
  return score >= 0.4 ? 'Most split' : score >= 0.2 ? 'Contested' : 'Mostly agreed';
}
export function pairwise(positions, left, right) {
  const a = new Map(positions.filter(p => p.guide_id === left && hasPosition(p)).map(p => [p.contest_id, p]));
  const shared = positions.filter(p => p.guide_id === right && hasPosition(p) && a.has(p.contest_id));
  const agree = [], differ = [];
  for (const p of shared) (positionKey(a.get(p.contest_id)) === positionKey(p) ? agree : differ).push(p.contest_id);
  return { count: shared.length, score: shared.length ? agree.length / shared.length : null, agree, differ };
}
export function rankGuides(guides, positions, answers) {
  return guides.map(guide => {
    const shared = positions.filter(p => p.guide_id === guide.id && ['yes', 'no'].includes(p.stance) && ['yes', 'no'].includes(answers[p.contest_id]));
    const matches = shared.filter(p => p.stance === answers[p.contest_id]).length;
    return { guide, count: shared.length, matches, score: shared.length ? matches / shared.length : null };
  }).sort((a, b) => (b.score ?? -1) - (a.score ?? -1) || b.count - a.count || a.guide.name.localeCompare(b.guide.name));
}
export function campAgreement(guides, positions) {
  const result = {};
  for (const camp of new Set(guides.map(g => g.camp))) {
    const members = guides.filter(g => g.camp === camp);
    let matches = 0, count = 0;
    for (let i = 0; i < members.length; i++) for (let j = i + 1; j < members.length; j++) {
      const pair = pairwise(positions, members[i].id, members[j].id);
      count += pair.count;
      matches += pair.agree.length;
    }
    result[camp] = { count, score: count ? matches / count : null };
  }
  return result;
}
