import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { candidateIds } from '../src/metrics.mjs';
export function validate(data) {
  const errors = [];
  const guides = new Map(data.guides.map(g => [g.id, g]));
  const contests = new Map(data.contests.map(c => [c.id, c]));
  if (guides.size !== data.guides.length || contests.size !== data.contests.length) errors.push('Duplicate guide or contest IDs');
  const seen = new Set(), counts = new Map();
  const validUrl = value => { try { return ['https:', 'http:'].includes(new URL(value).protocol); } catch { return false; } };
  for (const p of data.positions) {
    const label = `${p.guide_id}/${p.contest_id}`;
    const c = contests.get(p.contest_id);
    if (!guides.has(p.guide_id) || !c) errors.push(`${label}: unknown ID`);
    if (!validUrl(p.source_url)) errors.push(`${label}: invalid source_url`);
    if (!['high', 'low'].includes(p.confidence) || !Number.isFinite(Date.parse(p.retrieved_at))) errors.push(`${label}: invalid provenance`);
    if (seen.has(label)) errors.push(`${label}: duplicate cell`);
    seen.add(label);
    const abstention = ['no_position', 'no_recommendation_found'].includes(p.stance);
    let valid = abstention;
    if (c?.kind === 'measure') valid ||= ['yes', 'no'].includes(p.stance);
    if (c?.kind === 'race' && /^(candidate:|ranked:)/.test(p.stance)) {
      try {
        const ids = candidateIds(p.stance);
        valid ||= Array.isArray(ids) && ids.length > 0 && new Set(ids).size === ids.length && ids.every(id => c.candidates.some(candidate => candidate.id === id));
      } catch { valid = false; }
    }
    if (!valid) errors.push(`${label}: invalid stance ${p.stance}`);
    if (!abstention) counts.set(p.guide_id, (counts.get(p.guide_id) ?? 0) + 1);
  }
  for (const g of guides.values()) {
    if (!counts.get(g.id)) errors.push(`${g.id}: no positions; scraper may be broken`);
    for (const c of contests.values()) if (!seen.has(`${g.id}/${c.id}`)) errors.push(`${g.id}/${c.id}: missing cell`);
  }
  for (const c of contests.values()) {
    if (!c.topics.length || c.topics.some(t => !data.topics.includes(t))) errors.push(`${c.id}: invalid topics`);
    if (!validUrl(c.description_source_url)) errors.push(`${c.id}: missing description source`);
  }
  return errors;
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const data = JSON.parse(readFileSync(new URL('../data/dataset.json', import.meta.url)));
  const errors = validate(data);
  if (errors.length) { console.error(errors.join('\n')); process.exitCode = 1; }
  else console.log(`Validated ${data.positions.length} cited cells across ${data.guides.length} guides and ${data.contests.length} contests.`);
}
