}
function choice(p: Position, c: Contest): string {
  if (p.stance === 'yes') return 'Yes';
  if (p.stance === 'no') return 'No';
  if (p.stance === 'no_position') return 'Explicitly no position';
  if (p.stance === 'no_recommendation_found') return 'No recommendation found';
