}
function symbol(p: Position, c: Contest): string {
  if (p.stance === 'yes') return 'Y';
  if (p.stance === 'no') return 'N';
  if (p.stance === 'no_position') return '–';
  if (p.stance === 'no_recommendation_found') return '·';
  const ids = candidateIds(p.stance);
  if (ids.length > 1) return ids.length > 2 ? '3' : '2';
  const name = c.candidates.find(x => x.id === ids[0])?.name ?? '';
  return name.split(' ').filter(Boolean).map(x => x[0]).join('').slice(0,3);
}
function cellClass(p: Position, c: Contest): string {
