  return <>
    <a className="skip-link" href="#main">Skip to content</a>
    <header className="masthead"><a className="brand" href="?" aria-label="SF Ballot Atlas home"><span className="brand-mark">sf<span>↗</span></span><span>BALLOT<br/>ATLAS</span></a><div className="masthead-center">A FIELD GUIDE TO THE SAN FRANCISCO BALLOT</div><a className="about-link" href="?view=methodology" onClick={e=>{e.preventDefault();setView('methodology');}}>Independent. Sourced. Nonpartisan. <Icon name="arrow" size={15}/></a></header>
