        {customize && <div className="customize-panel"><div><h3>Visible guides</h3>{data.guides.map(g=><label key={g.id}><input type="checkbox" checked={!hiddenGuides.includes(g.id)} onChange={()=>toggle(g.id,hiddenGuides,setHiddenGuides)}/>{g.name}</label>)}</div><div><h3>Visible contests</h3><div className="contest-checks">{data.contests.map(c=><label key={c.id}><input type="checkbox" checked={!hiddenContests.includes(c.id)} onChange={()=>toggle(c.id,hiddenContests,setHiddenContests)}/>{c.name}</label>)}</div></div><button className="text-button" onClick={()=>{setHiddenGuides([]);setHiddenContests([]);}}>Show everything</button></div>}
        <div className="matrix-toolbar"><p><b>{visibleContests.length}</b> contests <span>×</span> <b>{visibleGuides.length}</b> guides <span className="toolbar-divider">|</span> <button className="text-button" onClick={reset}>Reset filters</button></p><label>Sort by <select aria-label="Sort contests" value={sort} onChange={e=>setSort(e.target.value)}><option value="split">Most disagreement</option><option value="ballot">Ballot order</option><option value="name">Contest name</option></select></label></div>
