          const currentBucket=splits[c.id].bucket;
          const showBucket=sort==='split' && (i===0 || splits[visibleContests[i-1].id].bucket!==currentBucket);
          return <React.Fragment key={c.id}>{showBucket&&<tr className="bucket-row"><th colSpan={visibleGuides.length+2}><div><span className={'bucket-label '+currentBucket.toLowerCase().replace(' ','-')}><i/>{currentBucket}</span><span className="bucket-description">{currentBucket==='Most split'?'40% or more dissent':currentBucket==='Contested'?'20–39% dissent':'Under 20% dissent'}</span></div></th></tr>}<tr className="contest-row"><th className="sticky" scope="row"><button className="contest-name" onClick={()=>openContest(c)}><strong>{c.name}</strong><span>{c.description === c.name ? (c.kind==='race' ? c.candidates.map(x=>x.name.split(' ').at(-1)).join(' · ') : c.description) : c.description}</span><i aria-hidden="true">↗</i></button></th><td><SplitBar c={c}/></td>{visibleGuides.map((g,j)=>{const p=pos(g.id,c.id);return <td key={g.id} className={j===0||visibleGuides[j-1].camp!==g.camp?'camp-start':''}><button className={'position '+cellClass(p,c)+(p.confidence==='low'?' unverified':'')} title={`${g.name}: ${choice(p,c)}${p.confidence==='low'?' · aggregator-only; review needed':''}${p.rationale?' · '+p.rationale:''}`} aria-label={`${g.name}: ${choice(p,c)} on ${c.name}${p.confidence==='low'?', aggregator-only':''}`} onClick={()=>openContest(c,g.id)}>{symbol(p,c)}{p.confidence==='low' && hasPosition(p) && <sup aria-hidden="true">*</sup>}</button></td>;})}</tr></React.Fragment>;
